mapper.select:
SELECT p.id, p.title, p.cover_image AS coverImage, p.price, p.original_price AS originalPrice, p.brand, p.model, p.condition_level AS conditionLevel, p.warranty, p.status, p.reject_reason AS rejectReason, p.view_count AS viewCount, p.favorite_count AS favoriteCount, p.create_time AS createTime, p.category_id AS categoryId, c.name AS categoryName, u.id AS sellerId, u.nickname AS sellerNickname, u.avatar AS sellerAvatar FROM biz_product p LEFT JOIN sys_category c ON c.id = p.category_id AND c.deleted = 0 LEFT JOIN sys_user u ON u.id = p.user_id
p.deleted = 0
AND p.status = 1
AND p.status = #{query.status}
AND p.user_id = #{query.sellerId}
AND p.category_id = #{query.categoryId}
AND p.condition_level = #{query.conditionLevel}
AND p.brand = #{query.brand}
AND p.price >= #{query.minPrice}
AND p.price <= #{query.maxPrice}
AND ( p.title LIKE CONCAT('%', #{query.keyword}, '%') OR p.brand LIKE CONCAT('%', #{query.keyword}, '%') OR p.model LIKE CONCAT('%', #{query.keyword}, '%') )
ORDER BY p.price ASC, p.id DESC
ORDER BY p.price DESC, p.id DESC
ORDER BY p.view_count DESC, p.id DESC
ORDER BY p.create_time DESC, p.id DESC
